	@Benchmark
	public long executeQuery() {
		return executeQuery(120);
	}

	public long executeQuery(int maxExecutionTimeSeconds) {
		OptionalLong expectedCountBindingValue = ThemeQueryCatalog.expectedCountBindingValueFor(theme, z_queryIndex);
		try (var connection = repository.getConnection()) {
			TupleQuery tupleQuery = prepareBenchmarkQuery(connection);
			tupleQuery.setMaxExecutionTime(maxExecutionTimeSeconds);
			QueryResultSummary result = evaluateQuery(tupleQuery, expectedCountBindingValue.isPresent());
			assertExpectedResult(result, expectedCountBindingValue);
			return benchmarkResult(result, expectedCountBindingValue);
		} catch (RuntimeException | Error failure) {
			printBenchmarkExplanation(maxExecutionTimeSeconds, isQueryInterrupted(failure), failure);
			throw failure;
		}
	}

	long executeCountQuery(String queryString, long expectedCountBindingValue, int maxExecutionTimeSeconds) {
		try (var connection = repository.getConnection()) {
			TupleQuery tupleQuery = connection.prepareTupleQuery(queryString);
			tupleQuery.setMaxExecutionTime(maxExecutionTimeSeconds);
			QueryResultSummary result = evaluateQuery(tupleQuery, true);
			assertExpectedCountQueryResult(queryString, result, expectedCountBindingValue);
			return result.countBindingValue;
		}
	}

	TimedCountQuery executeTimedCountQuery(String queryString, long expectedCountBindingValue,
			int maxExecutionTimeSeconds) {
		long started = System.nanoTime();
		try (var connection = repository.getConnection()) {
			TupleQuery tupleQuery = connection.prepareTupleQuery(queryString);
			tupleQuery.setMaxExecutionTime(maxExecutionTimeSeconds);
			long prepared = System.nanoTime();
			long rowCount = 0L;
			Long countBindingValue = null;
			long opened;
			try (TupleQueryResult result = tupleQuery.evaluate()) {
				opened = System.nanoTime();
				while (result.hasNext()) {
					BindingSet bindings = result.next();
					rowCount++;
					if (rowCount > 1) {
						throw new IllegalStateException("Expected exactly one count row for " + queryDescription()
								+ " but saw at least " + rowCount + " rows");
					}
					countBindingValue = countBindingValue(bindings);
				}
			}
			long completed = System.nanoTime();
			QueryResultSummary result = new QueryResultSummary(rowCount, countBindingValue);
			assertExpectedCountQueryResult(queryString, result, expectedCountBindingValue);
			return new TimedCountQuery(result.countBindingValue, prepared - started, opened - prepared,
					completed - opened);
		}
	}

	record TimedCountQuery(long countBindingValue, long preparationNanos, long openNanos, long consumptionNanos) {
	}

	private QueryResultSummary evaluateQuery(TupleQuery tupleQuery, boolean captureCountBinding) {
		long rowCount = 0L;
		Long countBindingValue = null;
		try (TupleQueryResult result = tupleQuery.evaluate()) {
			while (result.hasNext()) {
				BindingSet bindings = result.next();
				rowCount++;
				if (captureCountBinding) {
					if (rowCount > 1) {
						throw new IllegalStateException("Expected exactly one count row for " + queryDescription()
								+ " but saw at least " + rowCount + " rows");
					}
					countBindingValue = countBindingValue(bindings);
				}
			}
		}
		return new QueryResultSummary(rowCount, countBindingValue);
	}

	private Long countBindingValue(BindingSet bindings) {
		var value = bindings.getValue(COUNT_BINDING_NAME);
		if (value == null) {
			return null;
		}
		if (value instanceof Literal literal) {
			return literal.longValue();
		}
		throw new IllegalStateException("Unexpected aggregate binding type for " + COUNT_BINDING_NAME + ": " + value);
	}

	private void assertExpectedResult(QueryResultSummary result, OptionalLong expectedCountBindingValue) {
		if (result.rowCount != expected) {
			throw new IllegalStateException("Unexpected result row count for " + queryDescription() + ": expected "
					+ expected + " but got " + result.rowCount);
		}
		if (expectedCountBindingValue.isPresent()) {
			if (result.countBindingValue == null) {
				throw new IllegalStateException("Expected literal ?" + COUNT_BINDING_NAME + " binding for "
						+ queryDescription() + " but got null");
			}
			long expectedValue = expectedCountBindingValue.getAsLong();
			if (result.countBindingValue != expectedValue) {
				throw new IllegalStateException("Unexpected ?" + COUNT_BINDING_NAME + " binding for "
						+ queryDescription() + ": expected " + expectedValue + " but got " + result.countBindingValue);
			}
		}
	}

	private void assertExpectedCountQueryResult(String queryString, QueryResultSummary result,
			long expectedCountBindingValue) {
		if (result.rowCount != 1L) {
			throw new IllegalStateException("Expected exactly one count row for forced benchmark query but got "
					+ result.rowCount + "\n" + queryString);
		}
		if (result.countBindingValue == null) {
			throw new IllegalStateException("Expected literal ?" + COUNT_BINDING_NAME
					+ " binding for forced benchmark query but got null\n" + queryString);
		}
		if (result.countBindingValue != expectedCountBindingValue) {
			throw new IllegalStateException(
					"Unexpected ?" + COUNT_BINDING_NAME + " binding for forced benchmark query: expected "
							+ expectedCountBindingValue + " but got " + result.countBindingValue + "\n" + queryString);
		}
	}

	private long benchmarkResult(QueryResultSummary result, OptionalLong expectedCountBindingValue) {
		if (expectedCountBindingValue.isPresent()) {
			return result.countBindingValue;
		}
		return result.rowCount;
	}

	private void printBenchmarkExplanation(int maxExecutionTimeSeconds, boolean timedOut, Throwable originalFailure) {
		try {
			Explanation.Level level = benchmarkExplanationLevel(timedOut);
			try (var connection = repository.getConnection()) {
				TupleQuery tupleQuery = prepareBenchmarkQuery(connection);
				tupleQuery.setMaxExecutionTime(maxExecutionTimeSeconds);
				Explanation explain = tupleQuery.explain(level);
				System.out.println();
				System.out.println("\n### Query Explanation After Benchmark" + " theme=" + themeName + " queryIndex="
						+ z_queryIndex + " timedOut=" + timedOut + " level=" + level + " ###");
				System.out.println(explain);
				System.out.println();
			}
		} catch (RuntimeException | Error e) {
			if (originalFailure != null) {
				originalFailure.addSuppressed(e);
			} else {
				throw e;
			}
		}
	}

	Explanation.Level benchmarkExplanationLevel(boolean timedOut) {
		if (timedOut) {
			return Explanation.Level.Optimized;
		}
		return explanationLevel(queryExplanationLevel);
	}

	static Explanation.Level explanationLevel(String configured) {
		if (configured == null || configured.isBlank()) {
			return Explanation.Level.Timed;
		}
		String trimmed = configured.trim();
		for (Explanation.Level level : Explanation.Level.values()) {
			if (level.name().equalsIgnoreCase(trimmed)) {
				return level;
			}
		}
		try {
			return Explanation.Level.valueOf(trimmed.toUpperCase(Locale.ROOT));
		} catch (IllegalArgumentException e) {
			return Explanation.Level.Timed;
		}
	}

	private static boolean isQueryInterrupted(Throwable throwable) {
		Throwable current = throwable;
		while (current != null) {
			if (current instanceof QueryInterruptedException) {
				return true;
			}
			current = current.getCause();
		}
		return false;
	}

	private String queryDescription() {
		return themeName + " query " + z_queryIndex + " ("
				+ ThemeQueryCatalog.benchmarkQueryFor(theme, z_queryIndex).getName() + ")";
	}

	private void ensureDataLoadedAndValidated() throws IOException {
		DbFileSizes expectedDbFileSizes = readExpectedDbFileSizes();
		if (!hasExpectedDbFileSizes(expectedDbFileSizes)) {
			System.out.println(
					"Completed LMDB dataset metadata is missing or does not match the store. Rebuilding store from scratch.");
			DatasetSignature signature = rebuildStoreFromScratch();
			DbFileSizes sizes = currentDbFileSizes();
			expectedDbFileSizes = new DbFileSizes(sizes.triplesDataSizeBytes, sizes.valuesDataSizeBytes,
					readTripleTransactionId(), signature);
			if (!hasExpectedDbFileSizes(expectedDbFileSizes)) {
				throw new IllegalStateException("Completed LMDB dataset did not survive reopening the benchmark store");
			}
		}
		completedDbFileSizes = expectedDbFileSizes;
	}

	private void waitForSketchesIfEnabled() throws IOException {
		repository.init();
		if (storeConfig.getFrontierEstimatorMode() != FrontierEstimatorMode.OFF) {
			FrontierStatisticsAvailability frontierStatus = store.rebuildFrontierStatistics().availability();
			if (frontierStatus != FrontierStatisticsAvailability.READY) {
				throw new IOException("Frontier is not ready for Theme benchmark: " + frontierStatus);
			}
		}
		if (!sketchEstimatorEnabled && !waitForSketchesEnabled()) {
			return;
		}
		if (sketchEstimatorEnabled && !Boolean.parseBoolean(System.getProperty(WAIT_FOR_SKETCHES_PROPERTY, "true"))) {
			return;
		}
		long timeoutSeconds = Long.getLong(WAIT_FOR_SKETCHES_TIMEOUT_SECONDS_PROPERTY,
				DEFAULT_WAIT_FOR_SKETCHES_TIMEOUT_SECONDS);
		BenchmarkJoinEstimatorSupport.awaitEstimatorReady(store, "theme benchmark setup", timeoutSeconds,
				TimeUnit.SECONDS);
	}

	private void recordInitializedDbFileSizes() throws IOException {
		if (completedDbFileSizes == null || completedDbFileSizes.datasetSignature == null) {
			throw new IllegalStateException("Completed LMDB dataset identity is missing after setup validation");
		}
		DbFileSizes initialized = currentDbFileSizes();
		// These are minimum allocation bounds from the initialized store, before normal shutdown growth.
		completedDbFileSizes = new DbFileSizes(initialized.triplesDataSizeBytes, initialized.valuesDataSizeBytes,
				completedDbFileSizes.tripleTransactionId, completedDbFileSizes.datasetSignature);
	}

	private void writeCompletedDbFileSizesAfterShutdown() throws IOException {
		// The exact physical transaction identity is final only after all owned maintenance and shutdown finish.
		// Cache admission still compares it before initializing any existing repository on the next trial.
		writeExpectedDbFileSizes(new DbFileSizes(completedDbFileSizes.triplesDataSizeBytes,
				completedDbFileSizes.valuesDataSizeBytes, readTripleTransactionId(),
				completedDbFileSizes.datasetSignature));
	}

	private DatasetSignature rebuildStoreFromScratch() throws IOException {
		File directory = storeDirectory();
		if (repository != null) {
			repository.shutDown();
		}
		FileUtils.deleteDirectory(directory);
		if (!directory.exists() && !directory.mkdirs()) {
			throw new IOException("Unable to recreate fixed LMDB benchmark directory: " + directory);
		}
		storeConfig = createStoreConfig();
		storeConfig.setIterationCacheSyncThreshold(0);
		boolean buildSketches = sketchEstimatorEnabled || waitForSketchesEnabled();
		storeConfig.setSketchEstimatorEnabled(buildSketches);
		store = new LmdbStore(directory, storeConfig);
		repository = new SailRepository(store);
		if (buildSketches) {
			BenchmarkJoinEstimatorSupport.prepareEstimatorForBulkLoad(repository, store);
		}
		loadData();
		if (buildSketches) {
			BenchmarkJoinEstimatorSupport.persistEstimatorAfterBulkLoad(repository, store);
		}
		DatasetSignature signature = currentDatasetSignature();
		repository.shutDown();
		repository = null;
		store = null;
		System.gc();
		store = new LmdbStore(directory, storeConfig);
		repository = new SailRepository(store);
		return signature;
	}

	private LmdbStoreConfig createStoreConfig() {
		LmdbStoreConfig config = ConfigUtil.createConfig();
		boolean sketchProfile = sketchEstimatorEnabled || waitForSketchesEnabled();
		config.setSketchEstimatorEnabled(sketchProfile);
		config.setExperimentalQueryOptimizations(sketchProfile);
		config.setDirectAdjacencyEnabled(
				Boolean.parseBoolean(System.getProperty(WAIT_FOR_DIRECT_ADJACENCY_PROPERTY, "false")));
		config.setValueOverlayEnabled(
				Boolean.parseBoolean(System.getProperty(WAIT_FOR_VALUE_OVERLAY_PROPERTY, "false")));
		return config;
	}

	private DbFileSizes readExpectedDbFileSizes() throws IOException {
		File metadata = expectedDbFileSizeFile();
		if (!metadata.isFile()) {
			return missingExpectedDbFileSizes();
		}
		Properties properties = new Properties();
		try {
			try (var inputStream = new FileInputStream(metadata)) {
				properties.load(inputStream);
			}
			if (!hasCurrentDatasetRevision(properties)
					|| !storeConfig.getTripleIndexes().equals(properties.getProperty(TRIPLE_INDEXES_PROPERTY))
					|| !STORE_METADATA_VERSION.equals(properties.getProperty(STORE_METADATA_VERSION_PROPERTY))) {
				return missingExpectedDbFileSizes();
			}
			DatasetSignature signature = new DatasetSignature(
					parseSizeProperty(properties, VALUE_ENTRIES_PROPERTY),
					readCounts(properties, TRIPLE_DATABASES_PROPERTY), readContexts(properties));
			return new DbFileSizes(parseSizeProperty(properties, TRIPLES_DATA_SIZE_PROPERTY),
					parseSizeProperty(properties, VALUES_DATA_SIZE_PROPERTY),
					parseSizeProperty(properties, TRIPLE_TRANSACTION_ID_PROPERTY), signature);
		} catch (IllegalStateException | IllegalArgumentException failure) {
			System.out.println(
					"Ignoring invalid completed LMDB dataset metadata " + metadata + ": " + failure.getMessage());
			if (!metadata.delete()) {
				System.out.println("Unable to delete invalid completed LMDB dataset metadata: " + metadata);
			}
			return missingExpectedDbFileSizes();
		}
	}

	private void writeExpectedDbFileSizes(DbFileSizes expectedDbFileSizes) throws IOException {
		if (expectedDbFileSizes.datasetSignature == null || expectedDbFileSizes.tripleTransactionId < 0) {
			throw new IllegalArgumentException("Completed LMDB dataset identity is required for metadata persistence");
		}
		Properties properties = new Properties();
		properties.setProperty(TRIPLES_DATA_SIZE_PROPERTY, Long.toString(expectedDbFileSizes.triplesDataSizeBytes));
		properties.setProperty(VALUES_DATA_SIZE_PROPERTY, Long.toString(expectedDbFileSizes.valuesDataSizeBytes));
		properties.setProperty(TRIPLE_INDEXES_PROPERTY, storeConfig.getTripleIndexes());
		properties.setProperty(DATASET_REVISION_PROPERTY, DATASET_REVISION);
		properties.setProperty(STORE_METADATA_VERSION_PROPERTY, STORE_METADATA_VERSION);
		properties.setProperty(VALUE_ENTRIES_PROPERTY,
				Long.toString(expectedDbFileSizes.datasetSignature.valueEntries));
		properties.setProperty(TRIPLE_TRANSACTION_ID_PROPERTY, Long.toString(expectedDbFileSizes.tripleTransactionId));
		writeCounts(properties, TRIPLE_DATABASES_PROPERTY, expectedDbFileSizes.datasetSignature.tripleEntries);
		properties.setProperty(CONTEXTS_PROPERTY + ".count",
				Integer.toString(expectedDbFileSizes.datasetSignature.contexts.size()));
		int contextIndex = 0;
		for (String context : expectedDbFileSizes.datasetSignature.contexts) {
			properties.setProperty(CONTEXTS_PROPERTY + "." + contextIndex++ + ".name", context);
		}
		var destination = expectedDbFileSizeFile().toPath();
		var temporary = destination.resolveSibling(destination.getFileName() + ".tmp");
		try (var outputStream = new FileOutputStream(temporary.toFile())) {
			properties.store(outputStream, "Completed LMDB dataset for ThemeQueryBenchmark; sizes are minimums");
		}
		try {
			move(temporary, destination, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
		} catch (AtomicMoveNotSupportedException e) {
			move(temporary, destination, StandardCopyOption.REPLACE_EXISTING);
		}
	}

	private long parseSizeProperty(Properties properties, String propertyName) {
		String value = properties.getProperty(propertyName);
		if (value == null) {
			throw new IllegalStateException("Missing property " + propertyName);
		}
		try {
			long size = Long.parseLong(value);
			if (size < 0) {
				throw new IllegalStateException("Negative value for property " + propertyName + ": " + value);
			}
			return size;
		} catch (NumberFormatException e) {
			throw new IllegalStateException("Invalid long value for property " + propertyName + ": " + value, e);
		}
	}

	private DbFileSizes missingExpectedDbFileSizes() {
		return new DbFileSizes(-1L, -1L, -1L, null);
	}

	private DbFileSizes currentDbFileSizes() {
		return new DbFileSizes(dbFileSize(TRIPLES_DATA_FILE), dbFileSize(VALUES_DATA_FILE), -1L, null);
	}

	private boolean hasExpectedDbFileSizes(DbFileSizes expectedDbFileSizes) {
		if (expectedDbFileSizes.datasetSignature == null || expectedDbFileSizes.triplesDataSizeBytes <= 0
				|| expectedDbFileSizes.valuesDataSizeBytes <= 0 || expectedDbFileSizes.tripleTransactionId < 0) {
			return false;
		}
		DbFileSizes current = currentDbFileSizes();
		if (current.triplesDataSizeBytes < expectedDbFileSizes.triplesDataSizeBytes
				|| current.valuesDataSizeBytes < expectedDbFileSizes.valuesDataSizeBytes) {
			return false;
		}
		try {
			return expectedDbFileSizes.tripleTransactionId == readTripleTransactionId()
					&& expectedDbFileSizes.datasetSignature.equals(currentDatasetSignature());
		} catch (IOException | RepositoryException | SailException e) {
			System.out.println("Unable to validate cached LMDB dataset: " + e.getMessage());
			return false;
		}
	}

