	static String configuredForcedExecutionStrategy() {
		String configured = System.getProperty(FORCED_EXECUTION_STRATEGY_PROPERTY);
		return configured == null || configured.isBlank() ? null : configured;
	}

	private TupleQuery prepareBenchmarkQuery(SailRepositoryConnection connection) {
		TupleQuery tupleQuery = connection.prepareTupleQuery(query);
		if (forcedExecutionStrategy != null) {
			((SailQuery) tupleQuery).setForcedLmdbExecutionStrategy(forcedExecutionStrategy);
		}
		return tupleQuery;
	}

	private long countRowsAndVerifyCountBinding(TupleQueryResult evaluate, OptionalLong expectedCountBindingValue) {
		long count = 0;
		while (evaluate.hasNext()) {
			var bindingSet = evaluate.next();
			count++;
			if (expectedCountBindingValue.isPresent()) {
				if (count > 1) {
					throw new IllegalStateException("Expected exactly one count row for " + queryDescription()
							+ " but saw at least " + count + " rows");
				}
				var value = bindingSet.getValue(COUNT_BINDING_NAME);
				if (!(value instanceof Literal literal)) {
					throw new IllegalStateException("Expected literal ?" + COUNT_BINDING_NAME + " binding for "
							+ queryDescription() + " but got " + value);
				}
				long actualCountBindingValue = literal.longValue();
				long expectedValue = expectedCountBindingValue.getAsLong();
				if (actualCountBindingValue != expectedValue) {
					throw new IllegalStateException(
							"Unexpected ?" + COUNT_BINDING_NAME + " binding for " + queryDescription() + ": expected "
									+ expectedValue + " but got " + actualCountBindingValue);
				}
			}
		}
		if (expectedCountBindingValue.isPresent() && count == 0) {
			throw new IllegalStateException(
					"Expected exactly one count row for " + queryDescription() + " but query returned no rows");
		}
		return count;
	}

	void configureIrExecution() {
		if (z_z_irMode == null) {
			return;
		}
		if (!"disabled".equals(z_z_irMode) && !"auto".equals(z_z_irMode)) {
			throw new IllegalStateException("Unsupported IR benchmark parameter: " + z_z_irMode);
		}
		if (!previousIrProperties.isEmpty()) {
			throw new IllegalStateException("IR benchmark properties are already configured");
		}
		for (String property : IR_ENABLED_PROPERTIES) {
			configureIrProperty(property, "disabled".equals(z_z_irMode) ? "false" : null);
		}
		configureIrProperty(JANINO_CODEGEN_THRESHOLD_ROWS_PROPERTY, "0");
		if ("disabled".equals(z_z_irMode)) {
			configureIrProperty(JANINO_CODEGEN_SYNCHRONOUS_PROPERTY, "false");
		} else {
			configureIrProperty(JANINO_CODEGEN_SYNCHRONOUS_PROPERTY, "true");
		}
	}

	private void configureIrProperty(String property, String value) {
		previousIrProperties.put(property, System.getProperty(property));
		restoreProperty(property, value);
	}

	void restoreIrExecutionProperties() {
		previousIrProperties.forEach(ThemeQueryBenchmark::restoreProperty);
		previousIrProperties.clear();
	}

	private static void restoreProperty(String property, String previousValue) {
		if (previousValue == null) {
			System.clearProperty(property);
		} else {
			System.out.println("Restoring property " + property + "=" + previousValue);
			System.setProperty(property, previousValue);
		}
	}

	private boolean waitForSketchesEnabled() {
		return Boolean.parseBoolean(System.getProperty(WAIT_FOR_SKETCHES_PROPERTY, "false"));
	}

	private void waitForDirectAdjacencyIfEnabled() throws IOException {
		if (!Boolean.parseBoolean(System.getProperty(WAIT_FOR_DIRECT_ADJACENCY_PROPERTY, "false"))) {
			return;
		}
		repository.init();
		long timeoutSeconds = Long.getLong(WAIT_FOR_DIRECT_ADJACENCY_TIMEOUT_SECONDS_PROPERTY,
				DEFAULT_WAIT_FOR_DIRECT_ADJACENCY_TIMEOUT_SECONDS);
		try {
			if (!store.awaitDirectAdjacencyReady(timeoutSeconds, TimeUnit.SECONDS)) {
				throw new IOException("LMDB direct adjacency did not become exact within " + timeoutSeconds
						+ " seconds: " + store.getDirectAdjacencyReadinessDescription());
			}
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new IOException("Interrupted while waiting for LMDB direct adjacency", e);
		}
		System.out.println("LMDB direct adjacency is exact for the benchmark trial.");
	}

	private void waitForValueOverlayIfEnabled() throws IOException {
		if (!Boolean.parseBoolean(System.getProperty(WAIT_FOR_VALUE_OVERLAY_PROPERTY, "false"))) {
			return;
		}
		repository.init();
		long timeoutSeconds = Long.getLong(WAIT_FOR_VALUE_OVERLAY_TIMEOUT_SECONDS_PROPERTY,
				DEFAULT_WAIT_FOR_VALUE_OVERLAY_TIMEOUT_SECONDS);
		try {
			if (!store.awaitValueOverlayReady(timeoutSeconds, TimeUnit.SECONDS)) {
				throw new IOException("LMDB value overlay did not become ready within " + timeoutSeconds + " seconds");
			}
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new IOException("Interrupted while waiting for LMDB value overlay", e);
		}
		System.out.println("LMDB value overlay is ready for the benchmark trial.");
	}

	private void ensureSketchesAvailable(File storeDirectory) throws IOException {
		if (waitForSketchesEnabled()
				&& !new File(storeDirectory, JOIN_ESTIMATOR_SNAPSHOT_FILE).isFile()
				&& !new File(storeDirectory, JOIN_ESTIMATOR_METADATA_FILE).isFile()) {
			BenchmarkJoinEstimatorSupport.persistEstimatorAfterBulkLoad(repository, store);
		}
	}

	static boolean hasCurrentDatasetRevision(Properties properties) {
		return DATASET_REVISION.equals(properties.getProperty(DATASET_REVISION_PROPERTY));
	}

	private Map<String, Long> readCounts(Properties properties, String prefix) {
		long count = parseSizeProperty(properties, prefix + ".count");
		if (count == 0) {
			throw new IllegalStateException("Missing dataset counts for " + prefix);
		}
		var counts = new LinkedHashMap<String, Long>();
		for (long i = 0; i < count; i++) {
			String name = properties.getProperty(prefix + "." + i + ".name");
			if (name == null
					|| counts.put(name, parseSizeProperty(properties, prefix + "." + i + ".entries")) != null) {
				throw new IllegalStateException("Missing or duplicate dataset count name for " + prefix + "." + i);
			}
		}
		return counts;
	}

	private void writeCounts(Properties properties, String prefix, Map<String, Long> counts) {
		properties.setProperty(prefix + ".count", Integer.toString(counts.size()));
		int index = 0;
		for (var entry : counts.entrySet()) {
			properties.setProperty(prefix + "." + index + ".name", entry.getKey());
			properties.setProperty(prefix + "." + index + ".entries", Long.toString(entry.getValue()));
			index++;
		}
	}

	private Set<String> readContexts(Properties properties) {
		long count = parseSizeProperty(properties, CONTEXTS_PROPERTY + ".count");
		var contexts = new LinkedHashSet<String>();
		for (long i = 0; i < count; i++) {
			String context = properties.getProperty(CONTEXTS_PROPERTY + "." + i + ".name");
			if (context == null || !contexts.add(context)) {
				throw new IllegalStateException("Missing or duplicate dataset context for index " + i);
			}
		}
		return contexts;
	}

	private long readTripleTransactionId() throws IOException {
		// LMDB forbids separate environment handles for the same directory within a process. Probe only before
		// repository initialization (cache reuse) or after shutdown (completed bulk load), and close before init.
		if (repository != null && repository.isInitialized()) {
			throw new IllegalStateException("Triple transaction identity must be read while the repository is closed");
		}
		long environment = 0L;
		try (var stack = MemoryStack.stackPush()) {
			PointerBuffer pointer = stack.mallocPointer(1);
			checkCacheProbe(mdb_env_create(pointer));
			environment = pointer.get(0);
			checkCacheProbe(mdb_env_open(environment, new File(storeDirectory(), "triples").getAbsolutePath(),
					MDB_RDONLY | MDB_NOTLS, 0));
			MDBEnvInfo information = MDBEnvInfo.malloc(stack);
			checkCacheProbe(mdb_env_info(environment, information));
			return information.me_last_txnid();
		} finally {
			if (environment != 0L) {
				mdb_env_close(environment);
			}
		}
	}

	private static void checkCacheProbe(int result) throws IOException {
		if (result != MDB_SUCCESS) {
			throw new IOException("Unable to read LMDB triple transaction identity: " + mdb_strerror(result));
		}
	}

	private DatasetSignature currentDatasetSignature() {
		repository.init();
		var statistics = store.getLmdbStats();
		var tripleEntries = new LinkedHashMap<String, Long>();
		statistics.tripleDatabases().forEach((name, database) -> tripleEntries.put(name, database.entries()));
		var contextNames = new LinkedHashSet<String>();
		try (var connection = repository.getConnection()) {
			try (var contexts = connection.getContextIDs()) {
				while (contexts.hasNext()) {
					var context = contexts.next();
					contextNames.add(NTriplesUtil.toNTriplesString(context));
				}
			}
		}
		// Startup/close write ref-count and retirement metadata using copy-on-write pages. Their statistics and the
		// environment's physical length are not dataset identity. RDF dictionary entries, triple indexes and context
		// identities stay unchanged during query execution and derived estimator/adjacency maintenance. The persisted
		// triple transaction identity additionally rejects same-cardinality RDF mutations without scanning statements.
		return new DatasetSignature(statistics.valueDatabases().get("main").entries(), tripleEntries, contextNames);
	}

	static void loadAllThemeDatasets(SailRepository repository) throws IOException {
		try (var connection = repository.getConnection()) {
			var inserter = new RDFInserter(connection);
			for (Theme themeDataset : Theme.values()) {
				connection.begin(IsolationLevels.NONE);
				System.out.println("Loading theme dataset: " + themeDataset);
				ThemeDataSetGenerator.generate(themeDataset, inserter);
				connection.commit();
			}
		}
	}

	// @Benchmark
	public void print() {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			System.out.println("### Graphs in Store ###");
			connection.prepareTupleQuery("select distinct ?g where { graph ?g { ?s ?p ?o } }")
					.evaluate()
					.stream()
					.forEach(System.out::println);
			connection.getContextIDs().forEach(g -> System.out.println("Context: " + g));
		}
		System.out.println("###  ###");
	}

	private void printTypeMatrixMetricsIfEnabled() {
		if (!Boolean.getBoolean(TYPE_MATRIX_METRICS_PROPERTY)) {
			return;
		}
		try {
			Class<?> matrix = Class.forName("org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeTypeMatrix");
			System.out.println("### Type Matrix Metrics ###");
			for (String name : new String[] { "PLANE_MORSEL_RUNS", "PREDICATE_ROOTS_VISITED", "EDGE_FIBERS_VISITED",
					"UNIQUE_TARGETS_RESOLVED", "TARGET_TYPE_RUNS_DECODED", "SOURCE_TYPE_CACHE_HITS",
					"SOURCE_TYPE_CACHE_MISSES", "BORROWED_TYPE_SLICES", "SIDEWAYS_TYPE_MORSELS", "SIDEWAYS_SUBJECTS",
					"SIDEWAYS_EDGE_PROBES", "SIDEWAYS_EDGE_MATCHES", "SIDEWAYS_ROOT_COUNT_BATCHES",
					"LABEL_SYNOPSIS_SLICES", "PARALLEL_ADJACENCY_MORSELS", "PARALLEL_ADJACENCY_STEALS",
					"DENSE_TARGET_BREAKERS", "RADIX_TARGET_BREAKERS", "SIDEWAYS_REVERSE_RUNS",
					"NON_RESOURCE_PLANES_PRUNED" }) {
				Field field = matrix.getDeclaredField(name);
				field.setAccessible(true);
				System.out.println(name + "=" + ((AtomicLong) field.get(null)).get());
			}
			Class<?> datatypeHistogram = Class
					.forName("org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeDatatypeHistogram");
			for (String name : new String[] { "ADJACENCY_DOMAIN_RUNS", "ADJACENCY_PLANE_ROOTS", "ADJACENCY_PAGES",
					"PAGE_LITERAL_DATATYPE_FAST_PATHS", "PAGE_ROOT_IDS_DECODED", "BULK_LITERAL_HEADER_BATCHES",
					"SCALAR_LITERAL_HEADER_LOOKUPS", "UNIFORM_LITERAL_DATATYPE_BATCHES" }) {
				Field field = datatypeHistogram.getDeclaredField(name);
				field.setAccessible(true);
				System.out.println("DATATYPE_HISTOGRAM_" + name + "=" + ((AtomicLong) field.get(null)).get());
			}
			Class<?> intersection = Class
					.forName("org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeExistsIntersection");
			for (String name : new String[] { "DOMAIN_SYNOPSIS_INTERSECTIONS", "DOMAIN_PRESENCE_INTERSECTIONS",
					"DOMAIN_SYNOPSIS_STREAMING_INTERSECTIONS", "ADJACENCY_ROOT_INTERSECTIONS",
					"ADJACENCY_ROOTS_VISITED", "DOMAIN_SYNOPSIS_EVALUATION_NANOS", "DOMAIN_SYNOPSIS_PREPARATIONS" }) {
				Field field = intersection.getDeclaredField(name);
				field.setAccessible(true);
				System.out.println(name + "=" + ((AtomicLong) field.get(null)).get());
			}
			Class<?> runCountHistogram = Class
					.forName("org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeRunCountHistogram");
			for (String name : new String[] { "DENSE_ROOT_MORSELS", "ROOT_MERGE_FALLBACK_RANGES" }) {
				Field field = runCountHistogram.getDeclaredField(name);
				field.setAccessible(true);
				System.out.println("RUN_COUNT_HISTOGRAM_" + name + "=" + ((AtomicLong) field.get(null)).get());
			}
			Method getBackingStore = LmdbStore.class.getDeclaredMethod("getBackingStore");
			getBackingStore.setAccessible(true);
			Object backingStore = getBackingStore.invoke(store);
			Method directAdjacencyStore = backingStore.getClass().getDeclaredMethod("directAdjacencyStore");
			directAdjacencyStore.setAccessible(true);
			Object adjacencyStore = directAdjacencyStore.invoke(backingStore);
			Method memoryAccount = adjacencyStore.getClass().getDeclaredMethod("memoryAccount");
			memoryAccount.setAccessible(true);
			Object account = memoryAccount.invoke(adjacencyStore);
			Method memoryUsageSummary = account.getClass().getDeclaredMethod("memoryUsageSummary");
			memoryUsageSummary.setAccessible(true);
			System.out.println("DIRECT_ADJACENCY_" + memoryUsageSummary.invoke(account));
			Class<?> domainSynopsis = Class.forName("org.eclipse.rdf4j.sail.lmdb.LmdbNodeDomainSynopsis");
			Method domainDiagnostic = domainSynopsis.getDeclaredMethod("lastBuildDiagnostic");
			domainDiagnostic.setAccessible(true);
			System.out.println("DOMAIN_SYNOPSIS_BUILD=" + domainDiagnostic.invoke(null));
			Class<?> domainPresence = Class.forName("org.eclipse.rdf4j.sail.lmdb.LmdbNodeDomainPresence");
			Method presenceDiagnostic = domainPresence.getDeclaredMethod("lastBuildDiagnostic");
			presenceDiagnostic.setAccessible(true);
			System.out.println("DOMAIN_PRESENCE_BUILD=" + presenceDiagnostic.invoke(null));
			for (String name : new String[] { "INTERSECTION_CALLS", "INTERSECTION_NANOS" }) {
				Field field = domainPresence.getDeclaredField(name);
				field.setAccessible(true);
				System.out.println("DOMAIN_PRESENCE_" + name + "=" + ((AtomicLong) field.get(null)).get());
			}
			Class<?> adaptiveMemory = Class.forName("org.eclipse.rdf4j.sail.lmdb.csf.CsfAdaptiveMemory");
			Method claimedBytes = adaptiveMemory.getDeclaredMethod("claimedBytes");
			claimedBytes.setAccessible(true);
			System.out.println("CSF_ADAPTIVE_CLAIMED_BYTES=" + claimedBytes.invoke(null));
		} catch (ReflectiveOperationException e) {
			throw new IllegalStateException("Unable to read type-matrix benchmark metrics", e);
		}
	}

